#!/usr/bin/env node
// Patches the 3D contribution SVG generated by github-profile-3d-contrib
// so that instead of stopping permanently (repeatCount="1"), the animation loops
// continuously: grows up (~2s), holds at full height for 2 seconds, retracts, and restarts.
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { resolve, join } from 'node:path';

const TARGET_DIR = resolve(process.argv[2] || 'dist');

if (!existsSync(TARGET_DIR)) {
  console.log(`Directory ${TARGET_DIR} does not exist, skipping 3D animation patch.`);
  process.exit(0);
}

const files = readdirSync(TARGET_DIR).filter((f) => f.startsWith('profile-') && f.endsWith('.svg'));

if (files.length === 0) {
  console.log(`No profile-*.svg found in ${TARGET_DIR}`);
  process.exit(0);
}

// Timing parameters (in seconds):
// - grow: 2.0s (smooth rising of the 3D bars)
// - hold: 2.0s (holds at max height so stats and heights can be read)
// - retract: 0.6s (fluidly retracts back to base plane)
// Total loop duration = 4.6s, restarts continuously
const grow = 2.0;
const hold = 2.0;
const retract = 0.6;
const total = grow + hold + retract;

const k1 = '0';
const k2 = (grow / total).toFixed(3);
const k3 = ((grow + hold) / total).toFixed(3);
const k4 = '1';
const kt = `${k1};${k2};${k3};${k4}`;
const dur = `${total.toFixed(1)}s`;

for (const file of files) {
  const filePath = join(TARGET_DIR, file);
  let svg = readFileSync(filePath, 'utf8');

  let matchCount = 0;

  // 1. animateTransform (translate top of each 3D bar)
  svg = svg.replace(
    /<animateTransform\b([^>]*?)values="([^;]+);([^"]+)"([^>]*?)dur="[^"]+"([^>]*?)repeatCount="[^"]+"/g,
    (m, p1, v1, v2, p2) => {
      matchCount++;
      return `<animateTransform${p1}values="${v1};${v2};${v2};${v1}"${p2}keyTimes="${kt}" dur="${dur}" repeatCount="indefinite"`;
    }
  );

  // 2. animate height (left and right faces of each 3D bar)
  svg = svg.replace(
    /<animate\b([^>]*?)attributeName="height"([^>]*?)values="([^;]+);([^"]+)"([^>]*?)dur="[^"]+"([^>]*?)repeatCount="[^"]+"/g,
    (m, p1, p2, v1, v2, p3) => {
      matchCount++;
      return `<animate${p1}attributeName="height"${p2}values="${v1};${v2};${v2};${v1}"${p3}keyTimes="${kt}" dur="${dur}" repeatCount="indefinite"`;
    }
  );

  // 3. animate points (radar chart polygon)
  svg = svg.replace(
    /<animate\b([^>]*?)attributeName="points"([^>]*?)values="([^;]+);([^"]+)"([^>]*?)dur="[^"]+"([^>]*?)repeatCount="[^"]+"/g,
    (m, p1, p2, v1, v2, p3) => {
      matchCount++;
      return `<animate${p1}attributeName="points"${p2}values="${v1};${v2};${v2};${v1}"${p3}keyTimes="${kt}" dur="${dur}" repeatCount="indefinite"`;
    }
  );

  // 4. animate fill-opacity (pie chart slices and legend text)
  svg = svg.replace(
    /<animate\b([^>]*?)attributeName="fill-opacity"([^>]*?)values="([^"]+)"([^>]*?)dur="[^"]+"([^>]*?)repeatCount="[^"]+"/g,
    (m, p1, p2, vals, p3) => {
      matchCount++;
      const parts = vals.split(';');
      const first = parts[0];
      const last = parts[parts.length - 1];
      return `<animate${p1}attributeName="fill-opacity"${p2}values="${first};${last};${last};${first}"${p3}keyTimes="${kt}" dur="${dur}" repeatCount="indefinite"`;
    }
  );

  writeFileSync(filePath, svg, 'utf8');
  console.log(`  patched ${file}: ${matchCount} animations configured to loop continuously (dur=${dur}, hold=${hold}s)`);
}
